"""FastAPI entrypoint generated by the Roxira swarm orchestrator."""

from __future__ import annotations

from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from typing import Any

from fastapi import Depends, FastAPI
from sqlalchemy import text
from sqlalchemy.ext.asyncio import AsyncSession

import sys

from app.seed import seed_database
from app.db import DATABASE_URL, dispose_engine, get_session, init_models
from app.routers import ROUTERS


@asynccontextmanager
async def lifespan(app: FastAPI) -> AsyncIterator[None]:
    """Create the schema, seed the ledger, release the pool at shutdown."""
    await init_models()
    seeded = await seed_database()
    print(f"[startup] chart of accounts seeded: {seeded} rows", file=sys.stderr)
    yield
    await dispose_engine()


app = FastAPI(title='سامانه یکپارچه Erp سازمانی شامل حسابداری مالیاتی، ترازنامه،', version="1.0.0", lifespan=lifespan)

for _router in ROUTERS:
    app.include_router(_router)


@app.get("/health")
async def health() -> dict[str, str]:
    return {"status": "ok", "generator": "roxira-swarm", "database": DATABASE_URL}


@app.get("/health/db")
async def health_db(session: AsyncSession = Depends(get_session)) -> dict[str, Any]:
    """Readiness probe: proves the SQLite file answers queries."""
    await session.execute(text("SELECT 1"))
    return {"status": "ok", "database": DATABASE_URL}
